    private static readonly Dictionary<int, CodexCreature> _byId = All.ToDictionary(c => c.Id);

    private static readonly Dictionary<string, CodexCreature[]> _byName = All.GroupBy(c => c.Name, StringComparer.OrdinalIgnoreCase)
        .ToDictionary(g => g.Key, g => g.ToArray(), StringComparer.OrdinalIgnoreCase);

    /// <summary>The creature with game ID <paramref name="id"/> (a FellowshipLogs NPC actor's gameID); null when there is none.</summary>
    public static CodexCreature? ById(int id) => _byId.GetValueOrDefault(id);

    /// <summary>The one creature named <paramref name="name"/>; null when none or several have the name.</summary>
    public static CodexCreature? ByName(string name) => Named(name) is [var one] ? one : null;

    /// <summary>Every creature named <paramref name="name"/>, by ID.</summary>
    public static IReadOnlyList<CodexCreature> Named(string name) => _byName.GetValueOrDefault(name.Trim()) ?? [];
